// "Node.js" -> "nodejs", "Express JS" -> "expressjs"
const normalize = (label = "") => label.toLowerCase().replace(/[^a-z0-9]/g, "");

export const logoFor = (label) => {
  const n = normalize(label);
  if (!n) return null;
  for (const [re, key] of RULES) {
    if (re.test(n)) return key ? LOGOS[key] : null;
  }
  return null;
};